export interface RetryOptions { retries: number; baseMs: number }

// Full jitter: a random delay between 0 and the exponential bound.
export function delayFor(attempt: number, o: RetryOptions): number {
  return Math.random() * o.baseMs * 2 ** attempt;
}

export interface RetryOptions { retries: number; baseMs: number; maxMs?: number }

// Cap the delay so a long outage does not produce very long waits.
export function delayFor(attempt: number, o: RetryOptions): number {
  return Math.min(o.maxMs ?? 30_000, o.baseMs * 2 ** attempt);
}

export interface RetryOptions { retries: number; baseMs: number; maxMs?: number }

// Full jitter under a cap: random delay between 0 and min(maxMs, exponential bound).
export function delayFor(attempt: number, o: RetryOptions): number {
  return Math.random() * Math.min(o.maxMs ?? 30_000, o.baseMs * 2 ** attempt);
}

import { hmacSigner } from "./sign.ts";
import { delayFor, type RetryOptions } from "./retry.ts";

// Sign every retried request again, so each attempt carries a fresh signature.
export async function signedRetry(secret: string, o: RetryOptions, send: (sig: string) => Promise<Response>): Promise<Response> {
  const signer = hmacSigner(secret);
  for (let attempt = 0; ; attempt++) {
    const res = await send(await signer.sign("GET", "/", ""));
    if (res.ok || attempt >= o.retries) return res;
    await new Promise(r => setTimeout(r, delayFor(attempt, o)));
  }
}

