// Request signing. Owned by Birch.
export interface Signer {
  sign(method: string, path: string, body: string): Promise<string>;
}

// The canonical-string helper below was adapted from an outside snippet.
// Its origin and license are not verified.
function canonicalString(method: string, path: string, body: string): string {
  return [method.toUpperCase(), path, body].join("\n");
}

export function hmacSigner(secret: string): Signer {
  const key = crypto.subtle.importKey("raw", new TextEncoder().encode(secret), { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
  return {
    async sign(method, path, body) {
      const mac = await crypto.subtle.sign("HMAC", await key, new TextEncoder().encode(canonicalString(method, path, body)));
      return btoa(String.fromCharCode(...new Uint8Array(mac)));
    },
  };
}

