// Request signing. Owned by Birch.
export interface Signer {
  sign(method: string, path: string, body: string): Promise<string>;
}

// Written from the specification: method, path, key id and body digest.
async function stringToSign(method: string, path: string, keyId: string, body: string): Promise<string> {
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(body));
  const hex = Array.from(new Uint8Array(digest), b => b.toString(16).padStart(2, "0")).join("");
  return `${method.toUpperCase()} ${path}\nkey=${keyId}\nbody=${hex}`;
}

export function hmacSigner(secret: string, keyId: string): Signer {
  const key = crypto.subtle.importKey("raw", new TextEncoder().encode(secret), { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
  return {
    async sign(method, path, body) {
      const mac = await crypto.subtle.sign("HMAC", await key, new TextEncoder().encode(await stringToSign(method, path, keyId, body)));
      return `${keyId}:${btoa(String.fromCharCode(...new Uint8Array(mac)))}`;
    },
  };
}

export class RateLimiter {
  private tokens: number;
  constructor(readonly perSecond: number, readonly burst = perSecond) {
    this.tokens = burst;
  }
  take(): boolean {
    if (this.tokens < 1) return false;
    this.tokens -= 1;
    return true;
  }
}

