export interface ClientOptions { baseUrl: string; timeoutMs?: number; secret?: string }

export async function request(o: ClientOptions, path: string, body = ""): Promise<Response> {
  const headers: Record<string, string> = {};
  if (o.secret) headers["x-signature"] = await hmacSigner(o.secret).sign("GET", path, body);
  return fetch(new URL(path, o.baseUrl), { headers, signal: AbortSignal.timeout(o.timeoutMs ?? 10_000) });
}

