// Cove's request signer. Same Signer interface as src/sign.ts.
import type { Signer } from "./sign.ts";

export function coveSigner(secret: string): Signer {
  const key = crypto.subtle.importKey("raw", new TextEncoder().encode(secret), { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
  return {
    async sign(method, path, body) {
      const data = new TextEncoder().encode(`${method.toUpperCase()}\n${path}\n${body}`);
      const mac = await crypto.subtle.sign("HMAC", await key, data);
      return btoa(String.fromCharCode(...new Uint8Array(mac)));
    },
  };
}
